+if (typeof module !== 'undefined' && module.exports) {
+    module.exports = {
+        resolveInputContext: resolveInputContext,
+        buildLinkedQuery: buildLinkedQuery,
+        buildRecentCommentLines: buildRecentCommentLines
+    };
+}
